%%Emilijus Gureckas
%P4, 9var
%%
x = linspace(-1,1,50);
y = linspace(-1,1,50);

[X,Y] = meshgrid(x,y);
Z = 1 - (X.^2 + Y.^2);

figure %[output:5ebed3a8]

ax1 = subplot(1,3,1); %[output:5ebed3a8]
surf(X,Y,Z) %[output:5ebed3a8]
shading interp %[output:5ebed3a8]
colormap(ax1,parula) %[output:5ebed3a8]
xlabel('x') %[output:5ebed3a8]
ylabel('y') %[output:5ebed3a8]
zlabel('z') %[output:5ebed3a8]
title('Parula') %[output:5ebed3a8]
grid on %[output:5ebed3a8]

ax2 = subplot(1,3,2); %[output:5ebed3a8]
surf(X,Y,Z) %[output:5ebed3a8]
shading interp %[output:5ebed3a8]
colormap(ax2,hot) %[output:5ebed3a8]
xlabel('x') %[output:5ebed3a8]
ylabel('y') %[output:5ebed3a8]
zlabel('z') %[output:5ebed3a8]
title('Karšta') %[output:5ebed3a8]
grid on %[output:5ebed3a8]

ax3 = subplot(1,3,3); %[output:5ebed3a8]
surf(X,Y,Z) %[output:5ebed3a8]
shading interp %[output:5ebed3a8]
colormap(ax3,cool) %[output:5ebed3a8]
xlabel('x') %[output:5ebed3a8]
ylabel('y') %[output:5ebed3a8]
zlabel('z') %[output:5ebed3a8]
title('Šalta') %[output:5ebed3a8]
grid on %[output:5ebed3a8]

